export function SemanticHtml({
  semantic = {{semantic}},
  title = "{{title}}",
  showTagNames = {{showTagNames}},
  accent = "{{accent}}",
}) {
  const block = { padding: "10px 12px", borderRadius: 8, background: "#24143010", borderLeft: "3px solid " + accent };
  const tag = { display: "block", fontFamily: "ui-monospace, monospace", fontSize: 11, color: accent, marginBottom: 3 };
  const Header = semantic ? "header" : "div";
  const Nav = semantic ? "nav" : "div";
  const Main = semantic ? "main" : "div";
  return (
    <div style={{ width: 320, display: "flex", flexDirection: "column", gap: 6, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <Header style={block}>{showTagNames && <code style={tag}>{semantic ? "<header>" : '<div class="header">'}</code>}{title}</Header>
      <Nav style={block}>{showTagNames && <code style={tag}>{semantic ? "<nav>" : '<div class="nav">'}</code>}Overview &middot; Reports &middot; Settings</Nav>
      <Main style={{ ...block, minHeight: 40 }}>{showTagNames && <code style={tag}>{semantic ? "<main>" : '<div class="main">'}</code>}Page content</Main>
    </div>
  );
}
